//! The CSSOM-View element metrics Chrome 156 control
//! (`tests/fixtures/cssom_metrics_chrome156.json`, generated by turbo-dom's
//! `scripts/cssom-metrics-chrome-control.mjs`): every case is laid out through the live
//! HTML snapshot as turbo-surf takes it (`testing::layout_with`, surf's UA supplement),
//! and each `[data-cid]` element is read the way surf's CSSOM-View glue reads it —
//! `offsetLeft`/`offsetTop`/`offsetParent` from [`metrics::offset_position`], the boxes,
//! client rects, `offsetWidth`/`offsetHeight` and `client*` from
//! [`metrics::element_geometry`], plain inlines also through [`inline::geometry`] (the
//! glue's flattened-inline seam) — and compared with Chrome's. A case's `hits` are hit tested like
//! `document.elementsFromPoint` ([`hit::elements_at_point`], no scroll offsets) and the
//! whole topmost-first list is compared.
use std::collections::BTreeMap;

use serde_json::Value;

use crate::cssom_view::{hit, inline, metrics};
use crate::layout_snapshot::{LayoutSnapshot, Rect, SourceId};
use crate::live::source_id;
use crate::live::testing::{layout_with, DOCUMENT};

const FIXTURE: &str = include_str!("../../tests/fixtures/cssom_metrics_chrome156.json");

fn css_of(html: &str) -> &str {
    html.split_once("<style>")
        .and_then(|(_, rest)| rest.split_once("</style>"))
        .map_or("", |(css, _)| css)
}

/// The `data-cid` (else the local name) of the element whose source is `id`.
fn cid_of(tree: &turbo_dom::Tree, id: SourceId) -> Option<String> {
    let handle = tree.handles().find(|&h| source_id(DOCUMENT, h) == id)?;
    tree.get_attribute_local(handle, "data-cid")
        .or_else(|| tree.local_name(handle))
        .map(str::to_string)
}

/// A rect to 1/16 px (Chrome's `LayoutUnit` is 1/64 px; summed glyph advances differ from
/// Blink's by up to about 1/64 px, which a 1/16 px grid absorbs).
fn rect_text(rect: Rect) -> String {
    let unit = |v: f32| (v * 16.0).round() / 16.0;
    format!(
        "[{} {} {} {}]",
        unit(rect.x),
        unit(rect.y),
        unit(rect.width),
        unit(rect.height)
    )
}

fn fixture_rect(value: &Value) -> String {
    let n = |i: usize| value[i].as_f64().unwrap() as f32;
    rect_text(Rect {
        x: n(0),
        y: n(1),
        width: n(2),
        height: n(3),
    })
}

fn ints(value: &Value) -> Vec<i64> {
    value
        .as_array()
        .unwrap()
        .iter()
        .map(|v| v.as_i64().unwrap())
        .collect()
}

/// The element geometry the glue answers: its rects/bounds and offset/client sizes.
fn geometry_text(geometry: &metrics::ElementGeometry) -> String {
    let rects: Vec<String> = geometry.rects.iter().copied().map(rect_text).collect();
    format!(
        "bounds {} rects {rects:?} client {:?} size {:?}",
        rect_text(geometry.bounds),
        [
            geometry.client.left,
            geometry.client.top,
            geometry.client.width,
            geometry.client.height
        ]
        .map(i64::from),
        [geometry.offset.width, geometry.offset.height].map(i64::from),
    )
}

fn chrome_geometry(want: &Value) -> String {
    let rects: Vec<String> = want["rects"]
        .as_array()
        .unwrap()
        .iter()
        .map(fixture_rect)
        .collect();
    let offset = ints(&want["offset"]);
    format!(
        "bounds {} rects {rects:?} client {:?} size {:?}",
        fixture_rect(&want["bounds"]),
        <[i64; 4]>::try_from(ints(&want["client"])).unwrap(),
        [offset[2], offset[3]],
    )
}

fn geometry(
    snapshot: &LayoutSnapshot,
    styles: &crate::cssom_view::scroll::SourceStyles,
    id: SourceId,
) -> Result<metrics::ElementGeometry, String> {
    // As surf's glue (`live_layout_backend::element_geometry`): a `display: contents`
    // element has no boxes, and the root's client area is the viewport (CSSOM View
    // §6.1 `clientWidth`/`clientHeight` of the document element).
    let style = &styles[&id];
    if style.style.get("display") == Some("contents") {
        return Ok(metrics::empty_geometry());
    }
    // (Every element of these live snapshots has a border box, so the glue's
    // flattened-inline fallback to the inline seam is read separately below.)
    let mut geometry = metrics::element_geometry(snapshot, id)?;
    if style.parent.is_none() {
        let (width, height) = snapshot.viewport();
        geometry.client.width = width as i32;
        geometry.client.height = height as i32;
    }
    Ok(geometry)
}

/// Every read of `case`, as `(ours, Chrome's)` lines.
fn reads(case: &Value) -> (Vec<String>, Vec<String>) {
    let name = case["id"].as_str().unwrap();
    let html = case["html"].as_str().unwrap();
    let (tree, snapshot, styles) =
        layout_with(html, css_of(html), (1280.0, 800.0), Some(1.0), |_| {});
    let (mut got, mut chrome) = (Vec::new(), Vec::new());
    for want in case["boxes"].as_array().unwrap() {
        let cid = want["cid"].as_str().unwrap();
        let handle = tree
            .query_selector(&format!("[data-cid=\"{cid}\"]"))
            .unwrap();
        let id = source_id(DOCUMENT, handle);
        let label = format!("{name}: {cid}");
        got.push(format!(
            "{label} {}",
            geometry(&snapshot, &styles, id).map_or_else(|e| e, |g| geometry_text(&g))
        ));
        chrome.push(format!("{label} {}", chrome_geometry(want)));
        // A plain inline also reads through the bounded inline seam (the glue's
        // answer for a flattened inline): its bounds and offset size agree with
        // Chrome's (the seam unions a line's runs into one client rect per line, where
        // Chrome keeps one per inline box fragment).
        if name.starts_with("inline-")
            && tree.local_name(handle) == Some("span")
            && styles[&id].style.get("display") == Some("inline")
        {
            let offset = ints(&want["offset"]);
            got.push(format!(
                "{label} seam {}",
                inline::geometry(&snapshot, &styles, id).map_or_else(
                    |e| e,
                    |g| format!(
                        "{} {:?}",
                        rect_text(g.bounds),
                        [g.offset.width, g.offset.height].map(i64::from)
                    )
                )
            ));
            chrome.push(format!(
                "{label} seam {} {:?}",
                fixture_rect(&want["bounds"]),
                [offset[2], offset[3]]
            ));
        }
        let offset = ints(&want["offset"]);
        got.push(format!(
            "{label} offset {}",
            metrics::offset_position(&snapshot, &styles, id).map_or_else(
                |e| e,
                |o| format!(
                    "{} {} {:?}",
                    o.left,
                    o.top,
                    o.parent.and_then(|p| cid_of(&tree, p))
                )
            )
        ));
        chrome.push(format!(
            "{label} offset {} {} {:?}",
            offset[0],
            offset[1],
            want["parent"].as_str().map(str::to_string)
        ));
    }
    for want in case["hits"].as_array().into_iter().flatten() {
        let point = [want["x"].as_f64().unwrap(), want["y"].as_f64().unwrap()];
        got.push(format!(
            "{name}: hits {point:?} {}",
            hit::elements_at_point(&snapshot, &styles, &BTreeMap::new(), point).map_or_else(
                |e| e,
                |ids| format!(
                    "{:?}",
                    ids.iter().map(|&id| cid_of(&tree, id)).collect::<Vec<_>>()
                )
            )
        ));
        let names: Vec<Option<String>> = want["hits"]
            .as_array()
            .unwrap()
            .iter()
            .map(|v| v.as_str().map(str::to_string))
            .collect();
        chrome.push(format!("{name}: hits {point:?} {names:?}"));
    }
    (got, chrome)
}

/// Cases of open bugs, held out of [`element_metrics_and_hits_match_chrome_156`] and
/// asserted by [`held_out_cases_match_chrome_156`] (`#[ignore]`d until the fix lands):
/// miaskiewicz/turbo-dom#128 (a list marker hits its list item).
const HELD_OUT: &[&str] = &["hits-list-marker"];

/// The reads of every fixture case `select` picks, compared with Chrome's.
fn assert_cases_match(select: impl Fn(&str) -> bool) {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();
    assert!(fixture["chrome"].as_str().unwrap().starts_with("156."));
    let (mut got, mut chrome) = (Vec::new(), Vec::new());
    for case in fixture["cases"]
        .as_array()
        .unwrap()
        .iter()
        .filter(|case| select(case["id"].as_str().unwrap()))
    {
        let (ours, theirs) = reads(case);
        got.extend(ours);
        chrome.extend(theirs);
    }
    assert!(!chrome.is_empty());
    assert_eq!(got, chrome, "CSSOM-View reads differ from Chrome 156");
}

// Text in the bundled Liberation Serif.
#[cfg(feature = "bundled-fonts")]
#[test]
fn element_metrics_and_hits_match_chrome_156() {
    assert_cases_match(|id| !HELD_OUT.contains(&id));
}

#[test]
#[ignore = "miaskiewicz/turbo-dom#128: fails until the fix"]
fn held_out_cases_match_chrome_156() {
    assert_cases_match(|id| HELD_OUT.contains(&id));
}

/// miaskiewicz/turbo-dom#142: an `inline-block` holding text sits on its last line
/// box's baseline (CSS 2.1 §10.8.1), so the text beside it stays at y=8 and the
/// line box stays 18px tall.
#[cfg(feature = "bundled-fonts")]
#[test]
fn inline_block_text_baseline_matches_chrome_156() {
    assert_cases_match(|id| id == "inline-block-text-baseline");
}

#[test]
fn the_control_covers_every_read() {
    let fixture: Value = serde_json::from_str(FIXTURE).unwrap();
    let cases = fixture["cases"].as_array().unwrap();
    let reads: usize = cases.iter().map(|case| reads(case).1.len()).sum();
    assert_eq!((cases.len(), reads), (30, 216));
}
